css:
.lsm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lsm-root,.lsm-root *,.lsm-root *::before,.lsm-root *::after{box-sizing:border-box}
.lsm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lsm-root img{display:block;border:0;max-width:none}
.lsm-root [hidden]{display:none!important}
.lsm-root .n18_386{align-content:stretch;display:flex;flex-direction:column;align-items:flex-start;position:relative;flex-shrink:0;width:100%}
.lsm-root .n18_376{align-content:stretch;display:flex;gap:8px;align-items:center;position:relative;flex-shrink:0}
.lsm-root .n18_375{position:relative;flex-shrink:0;width:12px;height:12px}
.lsm-root .x31{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lsm-root .n18_364{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:color-mix(in srgb, var(--wa-text, rgb(255 255 255)) 50%, transparent);white-space:nowrap;width:21px}
.lsm-root .n18_383{word-break:break-word;align-content:stretch;display:flex;gap:2px;height:25px;align-items:baseline;justify-content:center;line-height:normal;font-style:normal;padding-top:3px;padding-bottom:3px;position:relative;flex-shrink:0;color:var(--wa-point, #bac1fa);width:100%;white-space:nowrap;border-style:solid;border-color:color-mix(in srgb, var(--wa-point, rgb(85 105 193)) 0%, transparent);border-width:0;border-bottom-width:1px}
.lsm-root .n18_365{font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;position:relative;flex-shrink:0;font-size:16px;width:20px;line-height:19px;white-space:nowrap}
.lsm-root .n18_410{font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:700;position:relative;flex-shrink:0;font-size:12px;width:12px;line-height:14px;white-space:nowrap}
.lsm-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lsm-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lsm-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lsm-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lsm-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lsm-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lsm-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.lsm-root[data-theme="light"] .n18_383{border-color:color-mix(in srgb, var(--wa-point, rgb(122 135 194)) 0%, transparent)}
